import re,subprocess
def _version_tuple(value):
    parts=tuple(int(x) for x in value.split('.'))
    return parts+(0,)*(3-len(parts))

def diagnose(binary):
    binary=str(binary)
    elf=subprocess.run(['readelf','--version-info',binary],capture_output=True,text=True,timeout=5)
    if elf.returncode:raise ValueError('not a readable ELF binary')
    required=sorted(set(re.findall(r'Name:\s+GLIBC_([0-9]+(?:\.[0-9]+)+)',elf.stdout)),key=_version_tuple)
    if not required:raise ValueError('no GLIBC version requirements found')
    host_result=subprocess.run(['ldd','--version'],capture_output=True,text=True,timeout=5)
    host_text=host_result.stdout+'\n'+host_result.stderr
    match=re.search(r'\b([0-9]+\.[0-9]+(?:\.[0-9]+)?)\b',host_text)
    if host_result.returncode or not match:raise RuntimeError('cannot determine host GLIBC version')
    host=match.group(1)
    missing=[version for version in required if _version_tuple(version)>_version_tuple(host)]
    return {'status':'incompatible' if missing else 'compatible','host_glibc':host,'required_glibc':required,'missing_glibc':missing}
